// Synchronous Blocking Syscall (User -> Kernel -> User transition)
ssize_t written = write(
    STDOUT_FILENO,      // System Call Number via Register/Stack
    data_buffer,        // User space data pointer
    buffer_size
);

if (written == -1) {
    // Syscall failed, kernel sets error code
    int err = errno;
}

// Syscalls and ECF Interruption (Non-linear path)
unsigned int remaining = sleep(10);

if (remaining > 0) {
    // The sleep syscall was interrupted by an ECF (e.g., a signal)
    // The kernel returns control prematurely (EINTR)
    handle_interruption();
}

// Clean termination vs Pure Syscall termination
// exit(): User-space cleanup (atexit, buffers) then _exit() syscall
void normal_exit() { exit(0); }

// _exit(): Immediate pure syscall (minimal ECF path)
void fast_exit() { _exit(0); }
